methods=['Baseline','Plan B\n250','Plan C\n100','API句子\n223','API段落\n97']; auc=[.985,.982,.974,.870,.978]; low=[None,.20,.23,222/223,20/97]
plt.style.use('seaborn-v0_8-whitegrid'); fig,ax=plt.subplots(figsize=(9,4.8)); x=np.arange(len(methods)); ax.bar(x,auc,color=['#274c77','#6096ba','#a3cef1','#f2b134','#d17a22']);ax.set_ylim(.8,1);ax.set_ylabel('AUROC');ax.set_title('SWAN detection performance across experiments');ax.set_xticks(x,methods);[ax.text(i,v+.003,f'{v:.3f}',ha='center') for i,v in enumerate(auc)];fig.tight_layout();fig.savefig(out/'auroc_comparison.png',dpi=180);plt.close(fig)
